// SPDX-License-Identifier: MIT
pragma solidity ^0.8.18;

/**
 * @title FinalCertificateManager
 * @author Your Name
 * @notice This contract manages the issuance and verification of digital certificates.
 * It defines roles for an owner, authorized institutions, and students.
 */
contract FinalCertificateManager {
    // --- STATE VARIABLES ---

    // The address of the person who deployed the contract. This is the main admin.
    address public owner;

    // A custom data type to define the structure of every certificate.
    struct Certificate {
        bytes32 id;                 // A unique ID for the certificate.
        string studentName;         // Name of the person receiving the certificate.
        string credentialName;      // Name of the course or degree.
        uint256 issueDate;          // The date the certificate was issued (as a timestamp).
        address issuingInstitution; // The address of the institution that issued it.
        bool isValid;               // A flag to confirm the certificate exists and is valid.
    }

    // A master list of all certificates, searchable by their unique ID.
    mapping(bytes32 => Certificate) public certificates;

    // An "allow list" of addresses that are authorized to issue certificates.
    mapping(address => bool) public authorizedInstitutions;

    // A list that tracks all certificate IDs for a specific student's address.
    // This is the key feature for the "Student Dashboard".
    mapping(address => bytes32[]) public studentCertificates;


    // --- EVENTS ---

    // An event is like a broadcast or a signal that something important happened.
    // Our frontend application can listen for this event to know when a new certificate is created.
    event CertificateIssued(bytes32 indexed certificateId, address indexed studentAddress, address indexed institutionAddress);


    // --- MODIFIERS ---

    // A modifier is a reusable security check. This one ensures only the 'owner' can run a function.
    modifier onlyOwner() {
        require(msg.sender == owner, "Only the owner can call this function.");
        _; // The underscore means "run the rest of the function's code now".
    }

    // This modifier ensures only an authorized college/employer can run a function.
    modifier onlyAuthorized() {
        require(authorizedInstitutions[msg.sender], "Caller is not an authorized institution.");
        _;
    }


    // --- FUNCTIONS ---

    /**
     * @notice The constructor is a special function that runs only once when the contract is deployed.
     * It sets the person who deploys the contract as the owner.
     */
    constructor() {
        owner = msg.sender;
    }

    /**
     * @notice Allows the owner to authorize a new institution (e.g., a college or employer).
     * @param _institutionAddress The wallet address of the institution to authorize.
     */
    function addInstitution(address _institutionAddress) public onlyOwner {
        authorizedInstitutions[_institutionAddress] = true;
    }

    /**
     * @notice Allows an authorized institution to issue a new certificate to a student.
     * @dev This function is for the "College Admin Page".
     * @param _studentAddress The wallet address of the student receiving the certificate.
     * @param _studentName The full name of the student.
     * @param _credentialName The name of the credential being issued (e.g., "B.Sc. Computer Science").
     */
    function issueCertificate(address _studentAddress, string memory _studentName, string memory _credentialName) public onlyAuthorized {
        bytes32 certificateId = generateCertificateId(_studentAddress, _credentialName);
        require(!certificates[certificateId].isValid, "This certificate has already been issued.");

        // Create the new certificate in memory
        Certificate memory newCertificate = Certificate({
            id: certificateId,
            studentName: _studentName,
            credentialName: _credentialName,
            issueDate: block.timestamp,
            issuingInstitution: msg.sender,
            isValid: true
        });

        // Save the new certificate to the blockchain
        certificates[certificateId] = newCertificate;

        // Add the certificate ID to the student's personal list
        studentCertificates[_studentAddress].push(certificateId);

        // Announce that a new certificate was issued
        emit CertificateIssued(certificateId, _studentAddress, msg.sender);
    }

    /**
     * @notice Retrieves a list of all certificate IDs for a given student.
     * @dev This function is for the "Student Dashboard".
     * @param _studentAddress The address of the student to look up.
     * @return A list of unique certificate IDs.
     */
    function getStudentCertificates(address _studentAddress) public view returns (bytes32[] memory) {
        return studentCertificates[_studentAddress];
    }

    /**
     * @notice Retrieves the full details for a single certificate using its ID.
     * @dev This function is for the "Verification Page".
     * @param _certificateId The unique ID of the certificate to look up.
     * @return The complete Certificate object.
     */
    function getCertificateDetails(bytes32 _certificateId) public view returns (Certificate memory) {
        return certificates[_certificateId];
    }

    /**
     * @notice A private helper function to create a unique, predictable ID.
     * @dev It combines the student's address and the credential name and hashes them.
     * @return A unique 32-byte hash.
     */
    function generateCertificateId(address _studentAddress, string memory _credentialName) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked(_studentAddress, _credentialName));
    }
}

